def parse_price(s: str) -> float:
    import re
    match = re.search(r'\$(\d{1,3}(,\d{3})*\.\d{2}|\d{1,3}(,\d{3})*|\d{1,3}(,\d{3})*\.\d{1,2})', s)
    if not match:
        raise ValueError('Invalid price format')
    price_str = match.group(1)
    price_str = price_str.replace(',', '')
    return float(price_str)

